from flask import Flask, request, jsonify, redirect, url_for, make_response, abort
app = Flask(__name__)
@app.before_request
def check_path():
    if request.path.startswith("/closed/"):
        return "Closed for practice", 403
@app.get("/closed/books")
def books():
    return "Books"
if __name__ == "__main__":
    app.run(host="127.0.0.1", port=8000)
